entries[1269663] = { ["name"] = "Secret Technique", ["text"] = "100 yd range\nInstant\nFinishing move that creates shadow clones of yourself. You and your shadow clones each perform a piercing attack on all enemies near your target, dealing Physical damage to the primary target and reduced damage to other targets.\n1 point : [(28.08% of Attack Power) * 3] total damage\n2 points: [(28.08% of Attack Power) * 2 * 3] total damage\n3 points: [(28.08% of Attack Power) * 3 * 3] total damage\n4 points: [(28.08% of Attack Power) * 4 * 3] total damage\n5 points: [(28.08% of Attack Power) * 5 * 3] total damage\n[ 6 points: [(28.08% of Attack Power) * 6 * 3] total damage] [ 7 points: [(28.08% of Attack Power) * 7 * 3] total damage]" }
entries[1269664] = { ["name"] = "Backstab", ["text"] = "100 yd range\nInstant\nStab the target, causing [(107.31% of Attack Power) * ((Max(0, Min( 90 - 10, 10)) * 11 + 260) / 370)] Physical damage. Damage increased by 20% when you are behind your target [ Improved Backstab : and critical strikes apply Find Weakness for 10 sec ].\n\nAwards 1 combo point." }
