entries[1269669] = { ["name"] = "Gloomblade", ["text"] = "100 yd range\nInstant\nPunctures your target with your shadow-infused blade for (123% of Attack Power) Shadow damage, bypassing armor. [ Improved Backstab : Critical strikes apply Find Weakness for 10 sec ]\nAwards 1 combo point." }
entries[1269674] = { ["name"] = "Goremaw's Bite", ["text"] = "100 yd range\nInstant\nLash out at your target and 2 additional nearby enemies, inflicting (630% of Attack Power) Shadow damage and causing them to Bleed for (1106% of Attack Power) damage over 14 sec.\n\n20% of all damage from Finishing Moves is repeated as Shadow, split evenly among affected enemies." }
entries[1269676] = { ["name"] = "Shadowstrike", ["text"] = "100 yd range\nInstant\nStrike the target, dealing (559% of Attack Power) Physical damage.\n\nWhile Stealthed, you strike through the shadows and appear behind your target up to 25 yds away, dealing 25% additional damage.\n\nAwards 2 combo points." }
